1206	
1207	  star = rewrite(star);
1208	  // Remember the last computed starLia under-approximation for `literal`; the
1209	  // model-value check in checkFullEffort uses it to skip refinement when the
1210	  // current model already satisfies it.
1211	  d_lastStarLia[literal] = star;
1212	
1213	  // Deactivate the guard from the previous refinement round for this literal:
1214	  // its under-approximation is a subset of the current `star`, so the tentative
1215	  // equivalence it guarded is subsumed. Asserting `(not g_old)` makes that
1216	  // guarded lemma vacuous, so the solver does not have to satisfy several
1217	  // (mutually constraining) guarded equivalences at once. Sound because `g_old`
1218	  // is fresh.
1219	  auto guardIt = d_lastGuard.find(literal);
1220	  if (guardIt != d_lastGuard.end())
1221	  {
1222	    Node deactivate = guardIt->second.notNode();
